// On-demand loader for the US GAAP Codex (src/data/asc/, generated by
// scripts/build_asc_codification.py).
//
// Nothing here is loaded at app launch. The Codex list, search and screen links run on the small
// ascIndex.json (utils/ascIndex). A FASB series file (asc_100s.json … asc_900s.json, the master
// cards) is pulled in with import() the first time a card in that series is opened, and a Topic's
// complete official text (text/asc_NNN.json, up to ~1.7 MB) only when its Official Text tab is
// opened. On web Metro emits each file as its own chunk; on iOS/Android (Hermes) the module is not
// evaluated until it is requested.
//
// Pure JS (no React Native imports) so it can be unit-tested in Node.

import { SERIES_IMPORTERS, TEXT_IMPORTERS } from './ascImporters';

export const ASC_SERIES_KEYS = Object.keys(SERIES_IMPORTERS);
export const ASC_TEXT_TOPICS = Object.keys(TEXT_IMPORTERS);

const seriesCache = new Map(); // series -> { series, category, cards }
const textCache = new Map(); // topic -> official text document
const inflight = new Map(); // key -> Promise
const listeners = new Set();

export const seriesOf = (topic) => `${String(topic).charAt(0)}00`;
export const isSeriesLoaded = (series) => seriesCache.has(series);
export const isTextLoaded = (topic) => textCache.has(String(topic));
export const loadedSeries = () => Array.from(seriesCache.keys());
export const loadedTexts = () => Array.from(textCache.keys());

/** Master card for a Topic if its series is already loaded, else null (never triggers a load). */
export const getLoadedCard = (topic) => seriesCache.get(seriesOf(topic))?.cards[String(topic)] || null;
/** Official text for a Topic if already loaded, else null (never triggers a load). */
export const getLoadedText = (topic) => textCache.get(String(topic)) || null;

/** Notified with a key ('series:800' or 'text:842') whenever a file finishes loading. */
export function subscribeAscLoads(fn) {
  listeners.add(fn);
  return () => listeners.delete(fn);
}

// Metro resolves import() of a JSON file to a namespace whose default export is the object;
// the Node test loader does the same.
const unwrap = (m) => (m && m.default ? m.default : m);

function once(key, cache, cacheKey, importer) {
  if (cache.has(cacheKey)) return Promise.resolve(cache.get(cacheKey));
  if (inflight.has(key)) return inflight.get(key);
  if (!importer) return Promise.reject(new Error(`Unknown ASC file "${key}"`));
  const p = importer()
    .then((m) => {
      const value = unwrap(m);
      cache.set(cacheKey, value);
      inflight.delete(key);
      listeners.forEach((fn) => fn(key));
      return value;
    })
    .catch((err) => {
      inflight.delete(key); // allow a retry
      throw err;
    });
  inflight.set(key, p);
  return p;
}

/** Loads (once) one FASB series file of master cards. */
export function loadSeries(series) {
  return once(`series:${series}`, seriesCache, series, SERIES_IMPORTERS[series]);
}

/** Loads the owning series and resolves to the Topic's master card (null if unknown). */
export async function loadCard(topic) {
  const t = String(topic);
  if (!TEXT_IMPORTERS[t]) return null;
  const s = await loadSeries(seriesOf(t));
  return s.cards[t] || null;
}

/** Loads (once) the complete official Codification text of one Topic. */
export function loadText(topic) {
  const t = String(topic);
  return once(`text:${t}`, textCache, t, TEXT_IMPORTERS[t]);
}
